   129→// Set writes value to the primary node + (rf-1) replicas.
   130→// Returns ErrNoAliveNodes if fewer than 1 replica is reachable.
   131→// Returns ErrReplicaFailure if fewer than quorum (rf/2+1) acknowledge.
   132→func (c *Cluster) Set(key, value string) error {
   133→	if key == "" {
   134→		return ErrEmptyKey
   135→	}
   136→
   137→	c.mu.RLock()
   138→	defer c.mu.RUnlock()
   139→
   140→	// Get replica nodes.
   141→	replicas, err := c.ring.GetN(key, c.rf)
   142→	if err != nil {
   143→		return err
   144→	}
   145→
   146→	// Filter to alive nodes.
   147→	alive := make([]string, 0, len(replicas))
   148→	for _, nodeID := range replicas {
   149→		if node, ok := c.nodes[nodeID]; ok && node.IsAlive() {
   150→			alive = append(alive, nodeID)
   151→		}
   152→	}
   153→
   154→	if len(alive) == 0 {
   155→		return ErrNoAliveNodes
   156→	}
   157→
   158→	// Compute quorum requirement.
   159→	quorum := c.rf/2 + 1
   160→
   161→	// Write to all alive replicas.
   162→	acks := 0
   163→	for _, nodeID := range alive {
   164→		if store, ok := c.stores[nodeID]; ok {
   165→			store.set(key, []byte(value))
   166→			acks++
   167→		}
   168→	}
   169→
   170→	if acks < quorum {
   171→		return ErrReplicaFailure
   172→	}
   173→
   174→	return nil
   175→}
