   177→// Get reads from the primary node. If the primary is dead,
   178→// falls back to the next live replica.
   179→func (c *Cluster) Get(key string) (string, error) {
   180→	c.mu.RLock()
   181→	defer c.mu.RUnlock()
   182→
   183→	// Get replica nodes in order.
   184→	replicas, err := c.ring.GetN(key, c.rf)
   185→	if err != nil {
   186→		return "", err
   187→	}
   188→
   189→	// Try each replica in order until we find an alive one with the key.
   190→	for _, nodeID := range replicas {
   191→		node, ok := c.nodes[nodeID]
   192→		if !ok || !node.IsAlive() {
   193→			continue
   194→		}
   195→
   196→		store, ok := c.stores[nodeID]
   197→		if !ok {
   198→			continue
   199→		}
   200→
   201→		val, found := store.get(key)
   202→		if found {
   203→			return string(val), nil
   204→		}
   205→	}
   206→
   207→	return "", ErrKeyNotFound
   208→}
   209→
   210→// Delete removes a key from all replicas.
   211→func (c *Cluster) Delete(key string) error {
   212→	c.mu.RLock()
   213→	defer c.mu.RUnlock()
   214→
   215→	// Get replica nodes.
   216→	replicas, err := c.ring.GetN(key, c.rf)
   217→	if err != nil {
   218→		return err
   219→	}
   220→
   221→	// Delete from all replicas.
   222→	found := false
   223→	for _, nodeID := range replicas {
   224→		if store, ok := c.stores[nodeID]; ok {
   225→			if store.delete(key) {
   226→				found = true
   227→			}
   228→		}
   229→	}
   230→
   231→	if !found {
   232→		return ErrKeyNotFound
   233→	}
   234→
   235→	return nil
   236→}
