   238→// NodeStatus returns the current status of a node.
   239→func (c *Cluster) NodeStatus(nodeID string) (NodeStatus, error) {
   240→	c.mu.RLock()
   241→	defer c.mu.RUnlock()
   242→
   243→	node, ok := c.nodes[nodeID]
   244→	if !ok {
   245→		return NodeAlive, ErrNodeNotFound
   246→	}
   247→
   248→	return node.Status, nil
   249→}
