    10→const DefaultVirtualNodes = 150
    11→
    12→// ringEntry represents one virtual node slot on the consistent hash ring.
    13→type ringEntry struct {
    14→	hash   uint32
    15→	nodeID string
    16→}
    17→
    18→// Ring implements consistent hashing over a sorted slice of ringEntries.
    19→type Ring struct {
    20→	entries      []ringEntry
    21→	nodeSet      map[string]bool
    22→	virtualNodes int
    23→	mu           sync.RWMutex
    24→}
    25→
    26→// NewRing creates a new Ring with the specified number of virtual nodes per physical node.
    27→func NewRing(virtualNodes int) *Ring {
    28→	return &Ring{
    29→		entries:      make([]ringEntry, 0, 256),
    30→		nodeSet:      make(map[string]bool),
    31→		virtualNodes: virtualNodes,
    32→	}
    33→}
    34→
    35→// Add places a node onto the ring by inserting virtualNodes entries.
    36→// It is idempotent: adding the same nodeID twice is a no-op.
    37→func (r *Ring) Add(nodeID string) {
    38→	r.mu.Lock()
    39→	defer r.mu.Unlock()
    40→
    41→	if r.nodeSet[nodeID] {
    42→		return // already present
    43→	}
    44→	r.nodeSet[nodeID] = true
    45→
    46→	// Insert virtualNodes entries for this physical node using binary insertion.
    47→	for i := 0; i < r.virtualNodes; i++ {
    48→		label := fmt.Sprintf("%s#%d", nodeID, i)
    49→		hash := r.hash(label)
    50→
    51→		// Find insertion position using binary search.
    52→		idx := sort.Search(len(r.entries), func(j int) bool {
    53→			return r.entries[j].hash >= hash
    54→		})
    55→
    56→		// Insert at idx by extending slice and copying.
    57→		r.entries = append(r.entries, ringEntry{})
    58→		copy(r.entries[idx+1:], r.entries[idx:])
    59→		r.entries[idx] = ringEntry{hash: hash, nodeID: nodeID}
    60→	}
    61→}
    62→
    63→// Remove deletes all virtual nodes for nodeID from the ring.
    64→func (r *Ring) Remove(nodeID string) {
    65→	r.mu.Lock()
    66→	defer r.mu.Unlock()
    67→
    68→	if !r.nodeSet[nodeID] {
    69→		return // not present
    70→	}
    71→	delete(r.nodeSet, nodeID)
    72→
    73→	// Filter out all entries belonging to this nodeID.
    74→	filtered := make([]ringEntry, 0, len(r.entries))
    75→	for _, entry := range r.entries {
    76→		if entry.nodeID != nodeID {
    77→			filtered = append(filtered, entry)
    78→		}
    79→	}
    80→	r.entries = filtered
    81→}
    82→
    83→// GetN returns up to n distinct physical node IDs starting from the successor
    84→// of hash(key). Used to select primary + replicas.
    85→// Returns ErrNoAliveNodes if the ring is empty.
    86→func (r *Ring) GetN(key string, n int) ([]string, error) {
    87→	r.mu.RLock()
    88→	defer r.mu.RUnlock()
    89→
    90→	if len(r.entries) == 0 {
    91→		return nil, ErrNoAliveNodes
    92→	}
    93→
    94→	keyHash := r.hash(key)
    95→
    96→	// Binary search to find the first entry >= keyHash.
    97→	pos := sort.Search(len(r.entries), func(i int) bool {
    98→		return r.entries[i].hash >= keyHash
    99→	})
   100→
   101→	if pos == len(r.entries) {
   102→		pos = 0 // wrap around to the beginning
   103→	}
   104→
   105→	// Collect up to n distinct physical node IDs using fixed array (n <= 8).
   106→	var result [8]string
   107→	var seen [8]string
   108→	var resultCount, seenCount int
   109→
   110→	for i := 0; i < len(r.entries) && resultCount < n; i++ {
   111→		idx := (pos + i) % len(r.entries)
   112→		nodeID := r.entries[idx].nodeID
   113→
   114→		// Check if already seen (linear search in small fixed array).
   115→		found := false
   116→		for j := 0; j < seenCount; j++ {
   117→			if seen[j] == nodeID {
   118→				found = true
   119→				break
   120→			}
   121→		}
   122→
   123→		if !found {
   124→			seen[seenCount] = nodeID
   125→			seenCount++
   126→			result[resultCount] = nodeID
   127→			resultCount++
   128→		}
   129→	}
   130→
   131→	return result[:resultCount], nil
   132→}
   133→
   134→// Get returns the primary node for key (convenience wrapper for GetN(key, 1)).
   135→func (r *Ring) Get(key string) (string, error) {
   136→	nodes, err := r.GetN(key, 1)
   137→	if err != nil {
   138→		return "", err
   139→	}
   140→	if len(nodes) == 0 {
   141→		return "", ErrNoAliveNodes
   142→	}
   143→	return nodes[0], nil
   144→}
   145→
   146→// Nodes returns a deduplicated list of all physical node IDs in the ring.
   147→func (r *Ring) Nodes() []string {
   148→	r.mu.RLock()
   149→	defer r.mu.RUnlock()
   150→
   151→	result := make([]string, 0, len(r.nodeSet))
   152→	for nodeID := range r.nodeSet {
   153→		result = append(result, nodeID)
   154→	}
   155→	return result
   156→}
   157→
   158→// hash computes a deterministic uint32 from a string using FNV-1a.
   159→// FNV-1a is 5-10x faster than SHA-256 for non-cryptographic hashing.
   160→func (r *Ring) hash(data string) uint32 {
   161→	h := fnv.New32a()
   162→	h.Write([]byte(data))
   163→	return h.Sum32()
   164→}
